package casbin

import (
	"fmt"
	"testing"
)

func TestZZProbe(t *testing.T) {
	e, err := NewEnforcer("examples/priority_model_explicit.conf")
	if err != nil {
		t.Fatalf("NewEnforcer: %v", err)
	}
	if _, err := e.AddPolicies([][]string{
		{"1", "carol", "data9", "read", "allow"},
		{"2", "alice", "data1", "read", "deny"},
		{"3", "alice", "data1", "read", "allow"},
		{"4", "bob", "data2", "write", "allow"},
	}); err != nil {
		t.Fatalf("AddPolicies: %v", err)
	}
	if _, err := e.RemovePolicy("1", "carol", "data9", "read", "allow"); err != nil {
		t.Fatalf("RemovePolicy: %v", err)
	}
	policy, err := e.GetPolicy()
	if err != nil {
		t.Fatalf("GetPolicy: %v", err)
	}
	var priorities []string
	for _, rule := range policy {
		priorities = append(priorities, rule[0])
	}
	fmt.Println("probe:", priorities)
}
EOF
